regras.esperado:
if (!conversa) {
  caixa.value = ''; caixa.style.height = 'auto';
  atualizarContador();
  bolha('user', texto, new Date().toISOString()); rolarFim();
  if (!token) {
    pensando(true);
    pensarStream([{ role: 'user', content: texto }], function () {}).then(function (r) {
      pensando(false);
      const t = (r && r.texto) || '';
      bolha('bot', t || 'travei agora — manda de novo que eu respondo.', new Date().toISOString(), '⚡ direto'); rolarFim();
      try { const h = JSON.parse(localStorage.getItem('rebocl_direto_h') || '[]'); h.push({ q: 'u', t: texto }); if (t) h.push({ q: 'b', t: t }); localStorage.setItem('rebocl_direto_h', JSON.stringify(h.slice(-60))); } catch (e) {}
    }).catch(function () { pensando(false); bolha('bot', 'a fiação piscou — manda de novo.', new Date().toISOString(), '⚡'); rolarFim(); });
    return;
  }
  $('btn-enviar').disabled = true;
  atualizarEstadoEntrega('criando-conversa');
  try {
    const inicio = Date.now();
    const nova = await api('/repos/' + REPO + '/issues', { method: 'POST', body: JSON.stringify({ title: texto.trim().split('\n')[0].slice(0, 70), body: texto.trim() }) });
    limparRascunhoPorChave('nova', texto);
    limparPreviaArquivoTexto();
    ultimoId = 0;
    atualizarEstadoEntrega('conversa-criada');
    await abrir(nova.number, nova.title, TURBO ? null : { inicio, evento: 'issues' });
    if (TURBO) {
      atualizarEstadoEntrega('resposta-local-solicitada');
      emergenciaResponder(nova.number);
    }
  } catch (e) {
    encerrarEstadoEntrega(estadoEntregaParaErro(e), '⚠️ entrega', mensagemErroSeguro(e));
    avisarRascunhoPreservadoAposFalha();
  } finally { $('btn-enviar').disabled = false; }
  return;
}

async function reabrirUltima() {
  try { if (token && localStorage.getItem('rebocl_conv')) { await abrir(parseInt(localStorage.getItem('rebocl_conv'), 10), localStorage.getItem('rebocl_conv_titulo') || ''); } } catch (e) {}
}
